	[435] = {
		id = 435,
		type1_words1 = "<p>◇皮肤扩招可能获得皮肤或家具。扩招时会消耗礼品卡或专属扭蛋券。\n</p><p>◇每十连扩招必定会获得皮肤，每30抽内必定会获得【豪华皮肤】</p><p>◇在扩招中获得已拥有的皮肤时，会返还【服装点】。【豪华皮肤】返5点【服装点】，【典藏皮肤】返3点【服装点】，【精选皮肤】返1点【服装点】</p><p>◇每次抽取皮肤扩招会额外获赠一点兑换点，消耗一定数量的兑换点可兑换皮肤扩招兑换商店中的皮肤一套。</p><p>◇因为概率公示存在小数点四舍五入情况，可能导致累加合不为100%。</p><p>【豪华皮肤】：迷情午夜、迷离午夜、日暮余晖、食之天堂、山溪幽径、特别任务、樱落凡尘、饮若人迷、甜心看护、特别直播、四好学生、安眠魔方、筝飞游野、奶茶假日、午夜之花、晨曦之花</p><p>【典藏皮肤】：温情夜语、悠然遣夏、生化幽灵、异种工程师、林中娇兔、丰黍瑞麟、曙光歌姬、极乐黄昏、街景魔术、娇花浅酌、午间故事、牛奶快派、暴走冲击、糯云兔心、惊悚博士、交彩之旅、熙阳青森、樱色凉风、金秋晚光、睡前夜话、跃动喷漆、前有恶兽、雀鸣行动、紫罗兰模特、此路不通</p><p>【精选皮肤】：学院女王、吉祥物、学生会长、打工女王、汪汪贵族、慵懒周末、钓鱼能手、特立独行、妙笔生花、偶像效应、闲暇时光、龙腾虎啸、庙会浴袍、天真烂漫、小小国王、班长日记、白色绵绵、饭后甜点、宛若琉璃、文学少女、科学班长、通学之路、睡前故事、邦妮派对、悠哉周末、优等生、潮玩乐天、淘气小熊、睡眼朦胧、练后小憩、红之夜曲、悠哉日常、蓝白海军、可爱正义、雪花与茶、甜蜜起点、机械师的假日、街头派对、游乐庆生、游戏时光</p>",
		words_type1 = "<p><span style=font-size: 24px; color: rgb(0, 150, 250);>扩招规则</span>\n</p>"
