	[526] = {
		id = 526,
		type1_words1 = "<p>◇服装扩招可能获得服装或家具。扩招时会消耗礼品卡或情人节专属服装扭蛋券。\n</p><p>◇每十连扩招必定会获得皮肤，每第30抽必定会获得【豪华皮肤】</span></p><p>◇在扩招中获得已拥有的稀有情人节服装时（【浓情帮佣】、【盒装情蜜】、【巧心馋猫】、【惊喜快递】、【蜜意圣代】、【初佣之爱】、【青涩季节】、【甜巧帕菲】、【浪漫之约】），会获得5张扭蛋券。</p><p>◇每次抽取服装扩招会额外获赠一点兑换点，消耗一定数量的兑换点可兑换当期服装扩招中的指定稀有服装一套（除惊喜快递）。</p><p>◇因为概率公示存在小数点四舍五入情况，可能导致累加合不为100%。</p><p>◇因存在<span style=color: rgb(0, 176, 240);>十连保底</span>内容，因此当十连时，服装概率会高于当前概率公示显示概率。</p>",
		words_type1 = "<p><span style=font-size: 24px; color: rgb(0, 150, 250);>扩招规则</span>\n</p>"
	},
